{
     "title": "CSCI-453: Computer Architecture - Foundations Lesson Blueprint",
     "learningObjectives": [
       "Define and explain the core components of a processor architecture, including registers, instruction sets, and memory hierarchy.",
       "Differentiate between user mode and privileged kernel mode, and describe how system calls and traps facilitate secure hardware interaction.",
       "Apply architectural concepts to simulate processor behavior, demonstrating how design choices impact performance and resource management."
     ],
     "beats": [
       {
         "title": "Introduction to Processor Architecture",
         "claim": "Computer architecture studies the design of both modern and classic computer hardware, focusing on how processors execute instructions and manage data.",
         "example": "A modern CPU processes instructions by fetching, decoding, and executing them in a pipeline, while classic architectures like the Von Neumann model separate instruction and data storage.",
         "visualDirection": "Display a side-by-side diagram of a classic Von Neumann architecture and a modern pipelined CPU, highlighting the fetch-decode-execute cycle.",
         "sourceIds": ["rit-csci-453"]
       },
       {
         "title": "Registers and Data Formats",
         "claim": "Registers are fast, processor-internal memory locations that store software-visible values and control data formats for operations.",
         "example": "In RISC-V, integer registers x1 through x31 hold software-visible values, while x0 always reads as zero, ensuring predictable data handling.",
         "visualDirection": "Show a register file layout with labeled x0-x31, emphasizing x0's zero-value constraint and data flow into/from memory.",
         "sourceIds": ["riscv-unprivileged"]
       },
       {
         "title": "Instruction Set and Operation Codes",
         "claim": "The RISC-V ISA defines programmer-visible instructions, operation codes, and memory operations that dictate how processors execute tasks.",
         "example": "Load instructions transfer data from memory into registers, while store instructions transfer register data to memory, forming the core data movement mechanism.",
         "visualDirection": "Illustrate a load/store instruction cycle with arrows showing data flow from memory to register (load) and register to memory (store).",
         "sourceIds": ["riscv-unprivileged"]
       },
       {
         "title": "Control Flow and Branching",
         "claim": "Branch and jump instructions change control flow, allowing processors to execute different code paths based on program logic.",
         "example": "Conditional branches redirect execution to different memory addresses when specific register values meet a condition, enabling loops and decision trees.",
         "visualDirection": "Draw a control flow graph with a branch instruction splitting into two paths, labeled with condition outcomes.",
         "sourceIds": ["riscv-unprivileged"]
       },
       {
         "title": "Memory Hierarchy and Addressing",
         "claim": "Addressing modes and data formats determine how processors locate and access memory, impacting performance and design efficiency.",
         "example": "Direct addressing loads data from a fixed memory address into a register, while indirect addressing uses a register value as the memory address.",
         "visualDirection": "Compare direct vs. indirect addressing with memory maps, showing register-to-memory address resolution steps.",
         "sourceIds": ["rit-csci-453"]
       },
       {
         "title": "User Mode vs. Privileged Kernel Mode",
         "claim": "Architecture analysis distinguishes user mode, privileged kernel code, and hardware translation to ensure secure system operation.",
         "example": "User mode runs unprivileged applications, while privileged kernel code handles system calls and manages hardware resources securely.",
         "visualDirection": "Show a two-tier memory model with user space and kernel space, highlighting permission bits and privilege levels.",
         "sourceIds": ["mit-xv6-book"]
       },
       {
         "title": "System Calls and Traps",
         "claim": "A system call transfers control from user code to a privileged kernel service, while a trap records processor state for exception handling.",
         "example": "When a process requests file I/O, a system call switches to kernel mode, and a trap captures registers to resume execution after completion.",
         "visualDirection": "Illustrate the system call sequence: user code -> trap -> kernel service -> return to user mode, with state capture points.",
         "sourceIds": ["mit-xv6-book"]
       },
       {
         "title": "Page Tables and Virtual Memory",
         "claim": "Page tables map virtual addresses to physical memory with permission bits, enabling virtual storage and secure isolation.",
         "example": "A page table entry translates a virtual address to a physical frame, with read/write/execute bits controlling access permissions.",
         "visualDirection": "Display a page table structure with virtual address bits, frame number, and permission bits, showing translation steps.",
         "sourceIds": ["mit-xv6-book"]
       },
       {
         "title": "Scheduling and Context Switching",
         "claim": "The scheduler selects runnable processes and switches processor context, managing concurrency and resource ownership.",
         "example": "When a process blocks on I/O, the scheduler picks another runnable process and saves the current processor state for later restoration.",
         "visualDirection": "Show a process scheduler with a ready queue, blocked queue, and context switch mechanism, highlighting state preservation.",
         "sourceIds": ["mit-xv6-book"]
       },
       {
         "title": "Practical Analysis Checklist",
         "claim": "Students simulate processor architectures to understand design choices, applying architectural state, data dependencies, and control dependencies.",
         "example": "A simulation tracks register values, memory operations, and control flow to verify that architectural state remains consistent across instructions.",
         "visualDirection": "Provide a checklist template with fields for architectural state, data dependencies, control dependencies, and simulation output validation.",
         "sourceIds": ["riscv-unprivileged", "mit-xv6-book"]
       }
     ]
   }
